package com.xiahu.reader;
import android.app.*;import android.os.Bundle;import android.content.*;import android.net.Uri;import java.io.*;import java.lang.reflect.*;import org.json.*;
/** Original text fixtures only. Uses isolated preferences; never changes the user's library. */
public final class LocalOrderTest extends Instrumentation {
 static void check(boolean v,String n){if(!v)throw new AssertionError(n);}
 static JSONObject request(String id,JSONArray files,JSONArray keys)throws Exception{return new JSONObject().put("id",id).put("fileIds",files).put("keys",keys);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle out=new Bundle();Context c=getTargetContext();SharedPreferences prefs=c.getSharedPreferences("local_order_fixture_only",0);prefs.edit().clear().commit();File[] sources={new File(c.getCacheDir(),"原创目录测试 第一卷.txt"),new File(c.getCacheDir(),"原创目录测试 第二卷.txt")};boolean ok=false;
 try{LocalBooks local=new LocalBooks(c);Field field=LocalBooks.class.getDeclaredField("prefs");field.setAccessible(true);field.set(local,prefs);JSONArray files=new JSONArray(),keys=new JSONArray();
 for(int i=0;i<sources.length;i++){try(OutputStream stream=new FileOutputStream(sources[i])){stream.write(("第一章 原创开篇\n这里是原创的第一章。\n第二章 原创续篇\n这里是原创的第二章。\n").getBytes("UTF-8"));}JSONObject book=local.importBook(Uri.fromFile(sources[i]),true);files.put(book.getString("id"));check(book.getString("workTitle").equals("原创目录测试"),"Same work extracted from filenames");JSONArray chapters=book.getJSONArray("chapters");for(int j=0;j<chapters.length();j++)keys.put(book.getString("id")+":"+chapters.getJSONObject(j).getString("id"));}
 check(local.all().length()==2&&keys.length()>=4,"Multiple files indexed separately with stable routing");JSONArray reversed=new JSONArray();for(int i=keys.length()-1;i>=0;i--)reversed.put(keys.getString(i));local.order(request("work_fixture",files,reversed));LocalBooks reopened=new LocalBooks(c);field.set(reopened,prefs);check(reopened.orders().getJSONObject("work_fixture").getJSONArray("keys").toString().equals(reversed.toString()),"Order survives new library instance");
 JSONArray invalid=new JSONArray(reversed.toString());invalid.put(0,"foreign:chapter");boolean refused=false;try{local.order(request("work_fixture",files,invalid));}catch(IOException e){refused=true;}check(refused,"Foreign keys rejected");invalid=new JSONArray(reversed.toString());invalid.put(0,invalid.getString(1));refused=false;try{local.order(request("work_fixture",files,invalid));}catch(IOException e){refused=true;}check(refused,"Duplicate keys rejected");refused=false;try{local.order(request("work_fixture",files,new JSONArray().put(keys.getString(0))));}catch(IOException e){refused=true;}check(refused,"Incomplete catalogue rejected");
 JSONObject first=local.find(files.getString(0));check(local.chapter(files.getString(0),0).toString().contains("原创"),"Source chapters still routed by original file index");local.order(request("work_fixture",files,keys).put("reset",true));check(!local.orders().has("work_fixture"),"Restore automatic removes manual preference");local.order(request("work_fixture",files,reversed));local.remove(files.getString(0));check(local.orders().has("work_fixture"),"Other file keeps remaining work order");local.remove(files.getString(1));check(!local.orders().has("work_fixture"),"Removed work prunes manual order");check(sources[0].length()>0&&sources[1].length()>0,"Original files unchanged");
 out.putString("report",new JSONObject().put("passed",true).put("multiFileWorkTitle",true).put("stableSourceChapterRouting",true).put("persistentManualOrder",true).put("invalidKeysRejected",true).put("automaticReset",true).put("removePrunesOrder",true).put("originalFilesPreserved",true).toString());ok=true;
 }catch(Throwable e){out.putString("failure",e.toString());}finally{prefs.edit().clear().commit();for(File f:sources)f.delete();}finish(ok?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
